#[cfg(test)] mod measured_raster_workload {
 use super::*;
 fn face(path:&str)->ttf::Face{load_face(&FaceInfo{path:path.into(),index:0,families:vec![],weight:400,italic:false}).unwrap()}
 #[test] fn measure_raster_workload(){
  let mode=std::env::var("RASTER_MODE").unwrap();let label=std::env::var("RASTER_LABEL").unwrap();
  for name in ["ascii","compound","bold","large","layers","bitmap","emoji"] {
   let pool=crate::resources::Budget::new(usize::MAX,usize::MAX);let _scope=crate::resources::Scope::enter(pool.clone());
   let size=if name=="large"{1200.0}else{32.0};
   let fonts=Fonts::outline(face("/System/Library/Fonts/Menlo.ttc"),None,vec![],vec![],size,1.0,String::new());
   let Source::Outline(outline)=&fonts.source else{unreachable!()};let font=&outline.regular;
   let emoji=if name=="emoji"{Some(face("/System/Library/Fonts/Apple Color Emoji.ttc"))}else{None};
   let bitmap=psf::Font::parse(TERMINUS_16).unwrap();
   let input=pool.snapshot().used;let initial_peak=pool.snapshot().peak;
   macro_rules! measure {($op:expr)=>{{
    if mode=="probe" {
     crate::raster_meter::start();let glyph=$op.unwrap();let(live,peak)=crate::raster_meter::stop();
     let checksum=match &glyph.pixels{Pixels::Alpha(p)=>p.iter().fold(0xcbf29ce484222325u64,|v,&b|(v^b as u64).wrapping_mul(0x100000001b3)),Pixels::Color(p)=>p.iter().fold(0xcbf29ce484222325u64,|v,&b|(v^b as u64).wrapping_mul(0x100000001b3))};
     let returned=pool.snapshot().used-input;let admitted=pool.snapshot().peak-input;
     if label=="after"{assert!(peak>=0 && peak as usize<=admitted);}
     eprintln!("RASTER_SAMPLE {{\"name\":\"{name}\",\"width\":{},\"height\":{},\"left\":{},\"top\":{},\"live_requested_bytes\":{live},\"peak_requested_bytes\":{peak},\"ledger_returned_bytes\":{returned},\"ledger_peak_bytes\":{admitted},\"initial_ledger_peak\":{initial_peak},\"checksum\":{checksum}}}",glyph.width,glyph.height,glyph.left,glyph.top);
     drop(glyph);assert_eq!(pool.snapshot().used,input);
    }else{
     drop($op.unwrap());let n=if name=="large"{20}else if name=="emoji"{100}else{1000};let start=std::time::Instant::now();
     for _ in 0..n{let glyph=$op.unwrap();std::hint::black_box(&glyph);drop(glyph);}
     eprintln!("RASTER_SAMPLE {{\"name\":\"{name}\",\"generate_drop_ns\":{},\"n\":{n}}}",start.elapsed().as_nanos()/n);
    }
   }}}
   match name{
    "ascii"|"large"=>measure!(outline.render(font,font.glyph_index('A'),false,fonts.cell_width)),
    "compound"=>measure!(outline.render(font,font.glyph_index('é'),false,fonts.cell_width)),
    "bold"=>measure!(outline.render(font,font.glyph_index('A'),true,fonts.cell_width)),
    "layers"=>measure!(outline.layered_glyph(font,font.glyph_index('A'),&[(font.glyph_index('A'),Some(0xffff0000)),(font.glyph_index('A'),Some(0x800000ff))],fonts.cell_width)),
    "bitmap"=>measure!(bitmap_glyph(&bitmap,'A',0)),
    "emoji"=>{let font=emoji.as_ref().unwrap();measure!(outline.color_glyph(font,font.glyph_index('😀'),fonts.cell_width*2));},
    _=>unreachable!()
   }
   drop(fonts);drop(emoji);assert_eq!(pool.snapshot().used,0);
  }
 }
}

